import uuid
from datetime import datetime, timezone
from sqlalchemy import (
    Column,
    String,
    Integer,
    Float,
    Boolean,
    DateTime,
    ForeignKey,
    JSON,
    Text,
)
from sqlalchemy.orm import relationship

from backend.app.database import Base


def generate_uuid() -> str:
    return str(uuid.uuid4())


def utc_now() -> datetime:
    return datetime.now(timezone.utc)


class GuardianPlanRecord(Base):
    """Persisted experiment plan generated by Guardian Intelligence."""
    __tablename__ = "guardian_plans"

    id = Column(String(36), primary_key=True, default=generate_uuid)
    version = Column(Integer, default=1, nullable=False)
    title = Column(String(255), nullable=False)
    goal = Column(Text, nullable=False)
    objective_type = Column(String(64), nullable=False)
    status = Column(String(32), default="proposed", nullable=False)
    requires_approval = Column(Boolean, default=True, nullable=False)
    approval_status = Column(String(32), default="pending", nullable=False)
    config_hash = Column(String(64), nullable=False, index=True)
    plan_json = Column(JSON, nullable=False)
    created_at = Column(DateTime, default=utc_now, nullable=False)
    updated_at = Column(DateTime, default=utc_now, onupdate=utc_now, nullable=False)

    # Relationships
    approvals = relationship("GuardianApprovalRecord", back_populates="plan", cascade="all, delete-orphan")
    executions = relationship("GuardianExecutionRecord", back_populates="plan", cascade="all, delete-orphan")
    evidence = relationship("GuardianEvidenceRecord", back_populates="plan", cascade="all, delete-orphan")


class GuardianApprovalRecord(Base):
    """User approval or rejection record bound strictly to a configuration hash."""
    __tablename__ = "guardian_approvals"

    id = Column(String(36), primary_key=True, default=generate_uuid)
    plan_id = Column(String(36), ForeignKey("guardian_plans.id"), nullable=False, index=True)
    config_hash = Column(String(64), nullable=False)
    approved_by = Column(String(128), default="user", nullable=False)
    decision = Column(String(32), default="approved", nullable=False)
    notes = Column(Text, nullable=True)
    is_valid = Column(Boolean, default=True, nullable=False)
    created_at = Column(DateTime, default=utc_now, nullable=False)

    # Relationships
    plan = relationship("GuardianPlanRecord", back_populates="approvals")


class GuardianExecutionRecord(Base):
    """Live or historical execution run of an approved Guardian experiment plan."""
    __tablename__ = "guardian_executions"

    id = Column(String(36), primary_key=True, default=generate_uuid)
    plan_id = Column(String(36), ForeignKey("guardian_plans.id"), nullable=False, index=True)
    status = Column(String(32), default="queued", nullable=False)
    current_step = Column(Integer, default=0, nullable=False)
    total_steps = Column(Integer, default=0, nullable=False)
    logs = Column(JSON, default=list, nullable=False)
    results_json = Column(JSON, default=dict, nullable=False)
    error_message = Column(Text, nullable=True)
    started_at = Column(DateTime, default=utc_now, nullable=False)
    completed_at = Column(DateTime, nullable=True)

    # Relationships
    plan = relationship("GuardianPlanRecord", back_populates="executions")
    evidence = relationship("GuardianEvidenceRecord", back_populates="execution", uselist=False)


class GuardianEvidenceRecord(Base):
    """Empirical observations, hypothesis outcomes, and grounded recommendations."""
    __tablename__ = "guardian_evidence"

    id = Column(String(36), primary_key=True, default=generate_uuid)
    plan_id = Column(String(36), ForeignKey("guardian_plans.id"), nullable=False, index=True)
    execution_id = Column(String(36), ForeignKey("guardian_executions.id"), nullable=True, index=True)
    cited_experiment_ids = Column(JSON, default=list, nullable=False)
    empirical_observations = Column(JSON, default=list, nullable=False)
    hypotheses_tested = Column(JSON, default=list, nullable=False)
    grounded_recommendations = Column(JSON, default=list, nullable=False)
    uncertainties_and_caveats = Column(JSON, default=list, nullable=False)
    created_at = Column(DateTime, default=utc_now, nullable=False)

    # Relationships
    plan = relationship("GuardianPlanRecord", back_populates="evidence")
    execution = relationship("GuardianExecutionRecord", back_populates="evidence")
